// Get the output from AI Agent
const aiOutput = $input.first().json.output;

// Clean with smart formatting
const cleanedOutput = aiOutput
  // First, unescape everything
  .replace(/\\n/g, '\n')
  .replace(/\\t/g, '  ')
  .replace(/\\"/g, '"')
  .replace(/\\'/g, "'")
  .replace(/\\\\/g, '\\')

  // Fix common formatting issues
  .replace(/\*\*(.*?)\*\*/g, '$1')      // Remove bold but keep text
  .replace(/\*(.*?)\*/g, '$1')          // Remove italic but keep text

  // Clean up spacing
  .replace(/\s*\n\s*/g, '\n')          // Remove spaces around newlines
  .replace(/\n{3,}/g, '\n\n')          // Limit consecutive newlines to 2

  // Ensure proper spacing after punctuation
  .replace(/([.!?])\s*\n/g, '$1\n\n')  // Add extra line after sentences
  .replace(/([a-z])\n([A-Z])/g, '$1 $2') // Fix sentences broken by newline

  // Final cleanup
  .trim();

// ⭐ RETURN PLAIN TEXT (NOT JSON OBJECT)
return [{
  json: {
    // This field will be used by the next node
    rawText: cleanedOutput
  }
}];
